pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface BossBaby {
    function owner() external view returns (address);
    function enableTrading() external;
    function tradingEnabled() external view returns (bool);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use the existing TARGET contract
        // and impersonate its owner in the exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address owner = BossBaby(TARGET).owner();

        // Impersonate the owner and enable trading
        vm.prank(owner);
        BossBaby(TARGET).enableTrading();

        // Verify trading is enabled
        bool tradingEnabled = BossBaby(TARGET).tradingEnabled();
        require(tradingEnabled == true, "Trading should be enabled");
        assertEq(tradingEnabled, true, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

